import { STAGES, createGameState, placeSticker, undoLast, getProgress, getAvailableIds, isValidDrop, serializeState, resetState } from './logic.js';
import { LEVEL, ITEMS, BY_ID } from './level.js';
import { wholePictureCamera, regionPictureCamera, clampViewportCamera, blendCamera } from './camera.js';
import { drawTweezers } from './sticker-fx.js';
import { makePaperBack, drawCurledSticker, drawGoldSpark, pressedPaperPoint } from './paper-motion.js';

const $ = id => document.getElementById(id);
const canvas = $('scene'), ctx = canvas.getContext('2d', { alpha: false });
const overlay = $('drag-layer'), dragCtx = overlay.getContext('2d');
const STORAGE_KEY = `scenery-stickers:${LEVEL.id}:v1`;
const SETTINGS_KEY = 'scenery-stickers:settings:v1';
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
const SPARK_DURATION = 1350;
const PICKUP_CURL = .26;
let state, settings = { sound:false, hints:true };
let persistent = true;
try {
  state = createGameState(localStorage.getItem(STORAGE_KEY));
} catch { state = createGameState(); persistent = false; }
try {
  const saved = JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
  if (saved && typeof saved==='object') settings = { sound:saved.sound===true, hints:saved.hints!==false };
} catch { /* Invalid preferences must not erase a valid painting. */ }
let baseImage, ready = false, sprites = new Map(), silhouettes = new Map(), paperBacks = new Map(), grips = new Map(), spriteLoads = new Map();
let width = 1, height = 1, dpr = 1, rect;
let view = { scale:1, tx:0, ty:0 }, cameraTween = null, cameraTour = null, fullView = false;
let selected = null, gesture = null, flight = null, burst = [], frameId = null;
let toastTimer = 0, stageTimer = 0, audioContext, lastTap = 0;
let transitionLocked = false, alive = true, exportURL = null;
let displayStageOverride = null;
let toolAngle = 2.58;
let regionEpoch=0;

function persist() {
  try { localStorage.setItem(STORAGE_KEY, serializeState(state)); }
  catch { persistent = false; }
  $('save-note').textContent = persistent ? '进度会自动保存' : '本次进度暂存于当前页面';
}
function persistSettings() {
  try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch {}
}
function toast(message) {
  clearTimeout(toastTimer);
  $('toast').textContent = message;
  $('toast').classList.add('visible');
  toastTimer = setTimeout(() => $('toast').classList.remove('visible'), 1800);
}
function loadImage(url) {
  return new Promise((resolve,reject) => {
    const img = new Image(); img.onload = () => resolve(img); img.onerror = () => reject(new Error('image load failed')); img.src = url;
  });
}
function makeSprite(item,img){
  const[x,y,w,h]=item.crop,ratio=Math.min(1,768/w,768/h);
  const sprite=document.createElement('canvas');sprite.width=Math.max(1,Math.round(w*ratio));sprite.height=Math.max(1,Math.round(h*ratio));
  sprite.getContext('2d').drawImage(img,x,y,w,h,0,0,sprite.width,sprite.height);sprites.set(item.id,sprite);
}
async function ensureSprites(ids){
  const pending=[...new Set(ids)].filter(id=>!sprites.has(id));
  let cursor=0;
  await Promise.all(Array.from({length:Math.min(6,pending.length)},async()=>{
    while(cursor<pending.length){
      const id=pending[cursor++];
      if(!spriteLoads.has(id))spriteLoads.set(id,loadImage(BY_ID[id].image).then(img=>makeSprite(BY_ID[id],img)).finally(()=>spriteLoads.delete(id)));
      await spriteLoads.get(id);
    }
  }));
}
function preparePaperTools(){
  const active=new Set(STAGES[state.stage].ids.filter(id=>!state.placedIds.includes(id)));
  for(const id of silhouettes.keys())if(!active.has(id)){silhouettes.delete(id);paperBacks.delete(id);}
  for (const id of active) {
    if(silhouettes.has(id)||!sprites.has(id))continue;
    const item=BY_ID[id],sprite=sprites.get(id),w=sprite.width,h=sprite.height;
    const grey = document.createElement('canvas'); grey.width = w; grey.height = h;
    const c = grey.getContext('2d'); c.drawImage(sprite,0,0);
    const pixels = c.getImageData(0,0,w,h);
    let grip={u:.22,v:.36},best=Infinity;
    for(let n=0;n<pixels.data.length;n+=4){
      if(pixels.data[n+3]>110){
        const u=(n/4%w)/w,v=Math.floor(n/4/w)/h;
        if(u>.55&&v>.55){const score=(u-.72)**2+(v-.87)**2;if(score<best){best=score;grip={u:u-.5,v:v-.5};}}
      }
      const tone=(pixels.data[n]*.2126+pixels.data[n+1]*.7152+pixels.data[n+2]*.0722)*.67;
      pixels.data[n]=tone;pixels.data[n+1]=tone+3;pixels.data[n+2]=tone;
    }
    c.putImageData(pixels,0,0);
    silhouettes.set(item.id,grey);
    paperBacks.set(item.id,makePaperBack(sprite));
    grips.set(item.id,grip);
  }
}
function fullCamera() {
  return wholePictureCamera(LEVEL,{width,height});
}
function clampCamera(camera) {
  return clampViewportCamera(camera,LEVEL,{width,height});
}
function stageCamera() {
  return regionPictureCamera(LEVEL,{width,height},STAGES[state.stage]);
}
function moveCamera(target, animate = true) {
  if (gesture || flight || transitionLocked) return;
  target = clampCamera(target);
  if (!animate || reducedMotion) { view = target; cameraTween = null; }
  else cameraTween = { from:{...view},to:target,start:performance.now(),duration:380 };
  schedule();
}
function resize() {
  const bounds = $('scene-shell').getBoundingClientRect();
  width = Math.max(1,bounds.width); height = Math.max(1,bounds.height);
  dpr = Math.min(devicePixelRatio || 1,2,Math.sqrt(2200000/(width*height)));
  canvas.width = Math.round(width*dpr); canvas.height = Math.round(height*dpr);
  resizeOverlay();
  rect = canvas.getBoundingClientRect();
  cancelGesture(false); cameraTween = null;
  if(cameraTour)finishRegionTour();
  view = state.completed || fullView ? fullCamera() : regionPictureCamera(LEVEL,{width,height},STAGES[displayStageOverride??state.stage]);
  schedule();
}
function turnPaper(){
  if(reducedMotion)return;
  const paper=document.querySelector('.sticker-paper');
  paper.classList.remove('page-turn');void paper.offsetWidth;paper.classList.add('page-turn');
}
function finishRegionTour(){
  const finished=state.completed;
  cameraTour=null;transitionLocked=false;displayStageOverride=null;fullView=finished;
  canvas.dataset.transition='idle';view=finished?fullCamera():stageCamera();updateUI();
  if(finished){
    toast('所有角落拼成了完整风景');
    renderArtwork($('complete-image'));openDialog('complete-dialog');
  }
}
function startRegionTour(){
  cameraTween=null;
  if(reducedMotion){view=state.completed?fullCamera():stageCamera();finishRegionTour();return;}
  cameraTour={from:{...view},overview:fullCamera(),to:state.completed?fullCamera():stageCamera(),start:performance.now(),phase:null};
  schedule();
}
function advanceRegionTour(now){
  const tour=cameraTour,elapsed=now-tour.start,outDuration=700,holdDuration=450,inDuration=800;
  const phase=elapsed<outDuration?'zoom-out':elapsed<outDuration+holdDuration?'overview':'zoom-in';
  if(tour.phase!==phase){
    tour.phase=phase;canvas.dataset.transition=phase;
    if(phase==='zoom-out')$('view-caption').textContent='这一角贴好了，看看整图';
    else if(phase==='overview'){fullView=true;$('view-caption').textContent='整幅风景';}
    else if(!state.completed){
      displayStageOverride=null;fullView=false;updateUI();turnPaper();
      $('view-caption').textContent=`放大${STAGES[state.stage].name}`;
    }
  }
  if(elapsed<outDuration)view=blendCamera(tour.from,tour.overview,elapsed/outDuration);
  else if(elapsed<outDuration+holdDuration)view={...tour.overview};
  else if(state.completed)finishRegionTour();
  else if(elapsed<outDuration+holdDuration+inDuration)view=blendCamera(tour.overview,tour.to,(elapsed-outDuration-holdDuration)/inDuration);
  else finishRegionTour();
}
function resizeOverlay() {
  overlay.width = Math.round(innerWidth*dpr); overlay.height = Math.round(innerHeight*dpr);
  schedule();
}
function screenToWorld(x,y) {
  rect = canvas.getBoundingClientRect();
  return { x:(x-rect.left-view.tx)/view.scale, y:(y-rect.top-view.ty)/view.scale };
}
function worldToScreen(x,y) {
  rect = canvas.getBoundingClientRect();
  return { x:rect.left+view.tx+x*view.scale, y:rect.top+view.ty+y*view.scale };
}
function targetCenter(item) { return {x:item.target.x+item.target.w/2,y:item.target.y+item.target.h/2}; }
function withinScene(x,y) {
  rect = canvas.getBoundingClientRect();
  return x>=rect.left && x<=rect.right && y>=rect.top && y<=rect.bottom;
}
function dropTolerance(item) { return Math.max(24,Math.min(43,Math.min(item.target.w,item.target.h)*view.scale*.48))/view.scale; }
function nearTarget(id,x,y) { return withinScene(x,y) && isValidDrop(BY_ID[id],screenToWorld(x,y),dropTolerance(BY_ID[id])); }
function drawSticker(c,item,alpha = 1) {
  c.globalAlpha = alpha;
  c.drawImage(sprites.get(item.id),item.target.x,item.target.y,item.target.w,item.target.h);
  c.globalAlpha = 1;
}
function renderScene(now) {
  ctx.setTransform(dpr,0,0,dpr,0,0); ctx.fillStyle = '#e5e3d7'; ctx.fillRect(0,0,width,height);
  ctx.save(); ctx.translate(view.tx,view.ty); ctx.scale(view.scale,view.scale);
  ctx.drawImage(baseImage,0,0,LEVEL.width,LEVEL.height);
  const activeIDs = STAGES[displayStageOverride??state.stage].ids;
  for (const item of [...ITEMS].sort((a,b)=>a.z-b.z)) {
    if (state.placedIds.includes(item.id)) drawSticker(ctx,item);
    else if (!state.completed && settings.hints && activeIDs.includes(item.id)) {
      const isSelected = selected===item.id || gesture?.id===item.id;
      ctx.save();ctx.globalAlpha = isSelected ? .7 : .49;
      ctx.shadowColor='#4f5c4650';ctx.shadowBlur=3/view.scale;ctx.shadowOffsetY=2/view.scale;
      ctx.drawImage(silhouettes.get(item.id),item.target.x,item.target.y,item.target.w,item.target.h);
      ctx.restore();
    }
  }
  for (const particle of burst) {
    const t = Math.max(0,Math.min(1,(now-particle.start)/SPARK_DURATION));
    ctx.globalAlpha = t<.10?t/.10:t<.68?1:Math.max(0,(1-t)/.32);
    ctx.fillStyle = particle.color;
    const px=particle.x+particle.dx*t,py=particle.y+particle.dy*t+15/view.scale*t*t;
    if(particle.star)drawGoldSpark(ctx,px,py,particle.r/view.scale*(.78+Math.sin(t*Math.PI)*.22),1);
    else if(particle.ray){
      const length=(7+3*Math.sin(t*Math.PI))/view.scale,norm=Math.hypot(particle.dx,particle.dy)||1;
      ctx.lineWidth=1.3/view.scale;ctx.strokeStyle=particle.color;ctx.lineCap='round';ctx.beginPath();
      ctx.moveTo(px-particle.dx/norm*length,py-particle.dy/norm*length);ctx.lineTo(px,py);ctx.stroke();
    }
    else {ctx.beginPath();ctx.arc(px,py,particle.r/view.scale,0,Math.PI*2);ctx.fill();}
  }
  ctx.globalAlpha = 1; ctx.restore();
  canvas.dataset.view = JSON.stringify(view);
}
function drawFloating(id,x,y,{alpha=1,w,h,curl=PICKUP_CURL,toolOpacity=1,toolOpen=0,retreat=0,ghost=false,mode='diagonal',spread=0,bend=1}={}) {
