.sticker.selected{background:transparent;box-shadow:none}
.sticker.selected canvas{filter:drop-shadow(1px 1px 0 #fff) drop-shadow(-1px -1px 0 #fff) drop-shadow(0 4px 3px #334d4640)}
.sticker span{visibility:hidden;height:0}
.sticker.dragging{opacity:0;width:0!important;min-width:0!important;padding-left:0;padding-right:0;overflow:hidden;transition:width .16s ease,padding .16s ease}
.sticker.placed{display:none}
.tray{justify-content:flex-start}
.tray[data-count="1"],.tray[data-count="2"],.tray[data-count="3"],.tray[data-count="4"]{justify-content:center}
.tray-navigation{display:flex;gap:3px;flex-shrink:0}
.tray-navigation[hidden]{display:none}
.tray-navigation button{border:0;background:#edf0e6;width:23px;height:24px;border-radius:3px;font-size:19px;line-height:1}
.chapters{min-width:0;overflow-x:auto;scrollbar-width:none}
.chapters::-webkit-scrollbar{display:none}
.chapter{flex:0 0 auto}
.chapter .chapter-name{display:none}
.chapter.current .chapter-name{display:inline}
.sticker-paper.page-turn .tray{animation:paper-turn .34s ease-out both}
@keyframes paper-turn{from{opacity:0;transform:translateX(46px)}to{opacity:1;transform:translateX(0)}}
@media(max-width:600px){
 .tray[data-count="3"],.tray[data-count="4"]{gap:4px;padding:3px 0}
 .tray[data-count="3"] .sticker{width:calc((100% - 8px)/3);min-width:0;padding:7px 5px 3px}
 .tray[data-count="4"] .sticker{width:calc((100% - 12px)/4);min-width:0;padding:7px 4px 3px}
 .tray[data-count="3"] .sticker canvas,.tray[data-count="4"] .sticker canvas{max-width:100%;object-fit:contain}
 .tray[data-count="4"] .sticker span{font-size:9px}
 .chapter.current .chapter-name{font-size:9px}
}

